use std::collections::HashMap;

/// A single tunable parameter for the renderer.
#[derive(Debug, Clone)]
pub struct Setting {
    pub key: String,
    pub value: i64,
}

#[derive(Default)]
pub struct ConfigBuilder {
    settings: Vec<Setting>,
    verbose: bool,
}

impl ConfigBuilder {
    pub fn new() -> Self {
        ConfigBuilder::default()
    }

    fn set(&mut self, key: &str, value: i64) -> &mut Self {
        self.settings.push(Setting {
            key: key.to_string(),
            value,
        });
        self
    }

    pub fn defaults(&mut self) -> &mut Self {
        self.set("width", 800);
        self.set("height", 600);
        self.set("max_fps", 144);
        self.set("cache_mb", 256);
        self
    }

    pub fn build(&self) -> HashMap<String, i64> {
        let mut out = HashMap::new();
        for setting in &self.settings {
            out.insert(setting.key.clone(), setting.value);
        }
        out
    }
}

